// ============================================================
// ORCHESTRATOR  (n8n logic, no LLM)
// 1. Picks the model for the whole chain   2. Validates input
// 3. Layer 1 guardrail: regex pre-screen for prompt injection
// ============================================================
const MODEL = 'openai/gpt-oss-120b';
// Options: 'qwen/qwen3.8-27b'  'openai/gpt-oss-120b'  'openai/gpt-oss-20b'

const MODEL_CONFIG = {
  'qwen/qwen3.8-27b':    { max_tokens: 1000 },
  'openai/gpt-oss-120b': { max_tokens: 2500, reasoning_effort: 'low' },
  'openai/gpt-oss-20b':  { max_tokens: 2500, reasoning_effort: 'low' }
};

const inp = $input.first().json;
const alert = inp.alert || {};

// --- Validation gate ---
const errors = [];
if (!alert.alert_id || !/^[A-Z]{3}-\d{4}$/.test(alert.alert_id)) errors.push('alert_id missing or malformed');
if (!alert.timestamp || isNaN(Date.parse(alert.timestamp))) errors.push('timestamp missing or unparseable');
if (!alert.source_tool) errors.push('source_tool missing');
if (JSON.stringify(alert).length > 48000) errors.push('payload exceeds context guard');

// --- Layer 1: injection pre-screen (flags, never blocks) ---
const INJECTION_PATTERNS = [
  /(ignore|disregard|override)\s+(all\s+)?(previous|prior|above)\s+(instructions|prompts)/i,
  /system\s*(note|prompt|instruction)\s*(for|to)\s*(ai|agent|llm)/i,
  /do\s+not\s+mention\s+(these|this|the)\s+instruction/i,
  /you\s+are\s+now/i,
  /instruction\s+override/i
];
const text = JSON.stringify(alert);
const matched = INJECTION_PATTERNS.filter(p => p.test(text)).map(p => p.source);

return [{ json: {
  ...inp,
  llm: { model: MODEL, params: MODEL_CONFIG[MODEL] || { max_tokens: 1000 } },
  valid: errors.length === 0,
  validation_errors: errors,
  injection_flag: matched.length > 0,
  injection_patterns_matched: matched,
  received_at: new Date().toISOString()
}}];

// ============================================================
// EXCEPTION: invalid input. Never reaches an agent. Logged for audit.
// ============================================================
const d = $input.first().json;
return [{ json: {
  status: 'REJECTED_INVALID_INPUT',
  source: d.source || 'manual',
  alert_id: d.alert?.alert_id ?? null,
  validation_errors: d.validation_errors,
  action: 'Returned to source for correction; routed to analyst queue for visibility',
  audit: { at: new Date().toISOString(), execution_id: $execution.id, stage: 'orchestrator_validation' }
}}];

